(function () {
  'use strict';
  // 内置官方 ballAction：隔离的显示层，只发非敏感控制指令；增强引擎仍在父页面。
  const MARK = '__nuojijiGhBallActionV1';
  const PLUGIN = 'nuojiji-gh-backup-companion';
  let seq = 0, connected = false, lastStatus = null, lastError = '';
  const el = id => document.getElementById(id);
  function request(action) {
    const requestId = String(Date.now()) + ':' + (++seq);
    window.parent.postMessage({ [MARK]: 1, pluginId: PLUGIN, action, requestId }, '*');
    return requestId;
  }
  function paint() {
    const busy = !!lastStatus?.busy;
    const p = lastStatus?.progress || {};
    el('state').textContent = !connected ? '未连接增强引擎，请确认一体化脚本已启用' :
      lastError ? lastError : busy ? (p.phase || 'GitHub 传输进行中…') :
      (p.phase && !p.active ? p.phase : '增强脚本已连接 · 当前空闲');
    el('sync').disabled = !connected || busy;
    el('import').disabled = !connected || busy;
    el('safe').disabled = !connected || busy;
    el('safe').textContent = lastStatus?.stableNetwork ? '✅ 稳定网络模式（2路）· 点击恢复高速' : '🔧 开启稳定网络模式（2路）';
    const cloudTime = Number(lastStatus?.cloudTime) || 0;
    el('time').textContent = cloudTime ? '云端时间：' + new Date(cloudTime).toLocaleString('zh-CN') : '云端时间：尚未读取';
    const total = Number(p.total) || 0, current = Number(p.current) || 0;
    // 官方进度与文件统计单位不同，只有百分比读取官方任务状态。
    const pct = typeof p.percent === 'number' && Number.isFinite(p.percent) ? p.percent : null;
    el('progress').hidden = !p.active;
    el('bar').style.width = (pct === null ? 25 : pct) + '%';
    el('bar').style.opacity = pct === null ? '.5' : '1';
    el('counts').textContent = p.active ? (
      (pct === null ? '正在等候官方进度' : '与原生悬浮窗同步 ' + pct + '%') +
      ' · 文件已处理 ' + current + (total ? '/' + total : '') +
      ' · 未变化 ' + (p.skipped || 0) +
      ' · 上传 blob ' + (p.blobUploaded || 0) +
      ' · 下载 ' + (p.networkDownloads || 0)
    ) : '';
  }
  window.addEventListener('message', event => {
    if (event.source !== window.parent) return;
    const d = event.data;
    if (!d || d[MARK] !== 1 || d.pluginId !== PLUGIN || d.kind !== 'response') return;
    connected = true;
    if (d.status && typeof d.status === 'object') lastStatus = d.status;
    if (d.error && d.ok === false) lastError = String(d.error);
    else if (d.finished) lastError = '';
    paint();
  });
  el('sync').addEventListener('click', () => {
    lastError = '';
    el('state').textContent = '正在请求原生流式上传…';
    request('sync');
  });
  el('import').addEventListener('click', () => {
    lastError = '';
    request('import');
    // 原生恢复有独立的确认对话框。关闭弹层以免挡住确认按钮。
    setTimeout(() => { try { window.nuo?.ui?.close?.(); } catch (_) {} }, 250);
  });
  el('refresh').addEventListener('click', () => { lastError = ''; request('cloudTime'); });
  el('diag').addEventListener('click', () => request('diagnostics'));
  el('safe').addEventListener('click', () => request('stableModeToggle'));
  request('ping');
  setInterval(() => request('status'), 1300);
  if (window.nuo && typeof window.nuo.ready === 'function') window.nuo.ready();
})();
